create extension if not exists pgcrypto;
create table if not exists public.learning_tasks(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, title text not null, subject text not null default 'General', objective text not null default '', status text not null default 'queued' check(status in ('queued','in_progress','completed','failed','paused')), progress int not null default 0 check(progress between 0 and 100), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.knowledge_items(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, task_id uuid references public.learning_tasks(id) on delete set null, title text not null, subject text not null default 'General', content text not null, source_type text not null default 'user_note', source_url text, created_at timestamptz not null default now());
create table if not exists public.learning_events(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, task_id uuid references public.learning_tasks(id) on delete set null, message text not null, created_at timestamptz not null default now());
alter table public.learning_tasks enable row level security; alter table public.knowledge_items enable row level security; alter table public.learning_events enable row level security;
create policy "own tasks" on public.learning_tasks for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own knowledge" on public.knowledge_items for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own events" on public.learning_events for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
